bool put_mode_to_mavlink(const open_platform_Data_Model_OperatingMode *data) {
  sb_queue_open_platform_Data_Model_OperatingMode_1_enqueue((sb_queue_open_platform_Data_Model_OperatingMode_1_t *) mode_to_mavlink_queue_1, (open_platform_Data_Model_OperatingMode *) data);

  return true;
}

bool last_error_status_payload;

bool get_error_status(bool *data) {
  sb_event_counter_t numDropped;
  bool fresh_data;
  bool isFresh = sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &error_status_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_error_status_payload = fresh_data;
  }
  *data = last_error_status_payload;
  return isFresh;
}

void init(void) {
  sb_queue_open_platform_Data_Model_OperatingMode_1_init((sb_queue_open_platform_Data_Model_OperatingMode_1_t *) mode_to_rx_queue_1);

  sb_queue_open_platform_Data_Model_OperatingMode_1_init((sb_queue_open_platform_Data_Model_OperatingMode_1_t *) mode_to_mavlink_queue_1);

  sb_queue_bool_1_Recv_init(&error_status_recv_queue, (sb_queue_bool_1_t *) error_status_queue_1);

  seL4_ModeManager_ModeManager_initialize();
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      seL4_ModeManager_ModeManager_timeTriggered();
      break;
    default:
      seL4_ModeManager_ModeManager_notify(channel);
  }
}
